begin;
do $test$
declare
  actor uuid;
  template public.wms_purchase_document%rowtype;
  source_line public.wms_purchase_document_line%rowtype;
  source_id uuid:=gen_random_uuid();
  source_line_id uuid:=gen_random_uuid();
  finance jsonb;
  estimate jsonb;
  estimate_first uuid;
  estimate_second uuid;
  finance_id uuid;
  blocked boolean;
  listing jsonb;
  other_supplier uuid;
begin
  select auth_user_id into actor from public.sys_user where auth_user_id is not null and user_roles @>array['R_SUPER'] limit 1;
  select * into template from public.wms_purchase_document where kind='purchase_inbound' and status='approved' and not is_initialization and supplier_id is not null and exists(select 1 from public.wms_purchase_document_line where document_id=wms_purchase_document.id) limit 1;
  select * into source_line from public.wms_purchase_document_line where document_id=template.id limit 1;
  if actor is null or source_line.id is null then raise exception 'Missing source-payable fixtures'; end if;
  perform set_config('request.jwt.claim.sub',actor::text,true);
  perform set_config('request.headers','{}',true);
  insert into public.wms_purchase_document select (jsonb_populate_record(null::public.wms_purchase_document,to_jsonb(template)||jsonb_build_object('id',source_id,'document_no','PAYABLE-TEST-'||source_id::text))).*;
  insert into public.wms_purchase_document_line select (jsonb_populate_record(null::public.wms_purchase_document_line,to_jsonb(source_line)||jsonb_build_object('id',source_line_id,'document_id',source_id,'line_no',10,'quantity',4,'base_quantity',40,'unit_price',100,'tax_inclusive_unit_price',113,'tax_rate',13,'amount',400,'tax_amount',52,'total_amount',452,'source_order_target_line_id',null,'movement_id',null))).*;
  estimate:=public.wms_push_purchase_payables_secure('estimated',jsonb_build_array(jsonb_build_object('document_id',source_id)))->0;
  estimate_first:=(estimate->>'id')::uuid;
  if (estimate->'lines'->0->>'base_quantity')::numeric<>40 then raise exception 'Source basic-unit conversion was lost'; end if;
  estimate:=public.fms_save_purchase_payable_secure(estimate||jsonb_build_object('lines',jsonb_build_array(estimate->'lines'->0||jsonb_build_object('quantity',2,'base_quantity',20))));
  select id into other_supplier from public.mdm_supplier where tenant_id=template.tenant_id and id<>template.supplier_id limit 1;
  if other_supplier is null then raise exception 'Missing source-supplier consistency fixture'; end if;
  blocked:=false;
  begin perform public.fms_save_purchase_payable_secure(estimate||jsonb_build_object('supplier_id',other_supplier)); exception when check_violation then blocked:=true; end;
  if not blocked then raise exception 'Source supplier substitution bypassed same-source reversal'; end if;
  estimate:=public.wms_push_purchase_payables_secure('estimated',jsonb_build_array(jsonb_build_object('document_id',source_id)))->0;
  estimate_second:=(estimate->>'id')::uuid;
  finance:=public.wms_push_purchase_payables_secure('financial',jsonb_build_array(jsonb_build_object('document_id',source_id)))->0;
  finance_id:=(finance->>'id')::uuid;
  if finance->'lines'->0->>'estimated_line_id' is not null then raise exception 'Unexpected initial source association'; end if;
  perform public.fms_act_purchase_payable_secure(array[finance_id],'submit');
  blocked:=false;
  begin perform public.fms_act_purchase_payable_secure(array[finance_id],'approve'); exception when check_violation then blocked:=true; end;
  if not blocked then raise exception 'Financial approval bypassed pending same-source estimates'; end if;
  perform public.fms_act_purchase_payable_secure(array[estimate_first,estimate_second],'submit');
  perform public.fms_act_purchase_payable_secure(array[estimate_first,estimate_second],'approve');
  perform public.fms_act_purchase_payable_secure(array[finance_id],'approve');
  if (select count(*) from public.fms_purchase_payable_line where document_id=finance_id and estimated_line_id is not null)<>2 then raise exception 'Late source association did not split across both estimates'; end if;
  if (select sum(total_amount) from public.fms_purchase_payable_line where document_id=finance_id)<>452 then raise exception 'Split financial total changed'; end if;
  if (select sum((line_snapshot->>'base_quantity')::numeric) from public.fms_purchase_payable_line where document_id=finance_id)<>40 then raise exception 'Split financial basic quantities duplicated the source total'; end if;
  if (select -sum(payable_line.total_amount) from public.fms_purchase_payable_line payable_line join public.fms_purchase_payable_document payable_document on payable_document.id=payable_line.document_id where payable_document.reversal_source_id=finance_id)<>452 then raise exception 'Same-source reversal lost one estimated tranche'; end if;
  if (select sum((payable_line.line_snapshot->>'base_quantity')::numeric) from public.fms_purchase_payable_line payable_line join public.fms_purchase_payable_document payable_document on payable_document.id=payable_line.document_id where payable_document.reversal_source_id=finance_id)<>-40 then raise exception 'Reversal basic quantities did not invert the source conversion'; end if;
  perform public.fms_act_purchase_payable_secure(array[finance_id],'freeze','明细余额验证',113);
  listing:=public.fms_purchase_payable_list_secure('financial','',finance_id,20,0,jsonb_build_object('view_mode','line'));
  if jsonb_array_length(listing->'data')<>2 then raise exception 'Line mode did not return both split rows'; end if;
  if (listing->'data'->0->>'unpaid_amount')::numeric<>226 or (listing->'data'->0->>'matched_amount')::numeric<>226 then raise exception 'Line mode duplicated document balances'; end if;
  if (select sum((row_data->>'frozen_amount')::numeric) from jsonb_array_elements(listing->'data') row_data)<>113 then raise exception 'Line frozen balances do not reconcile to document'; end if;
end $test$;
rollback;
